//! Producing Belay's output files.
//!
//! Agents, skills, and commands each become one Markdown file in the agent
//! directory. Instructions are different: they mirror the shape tree onto the
//! code tree, concatenating everything written at one scope into the
//! `AGENTS.md` for the matching code directory. Self-instructions are about the
//! specification rather than the code, so each one lands in the `AGENTS.md` of
//! the directory it is written in.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use piton_core::compile::Compilation;
use piton_core::diag::Diagnostic;
use piton_core::framework::OutputFile;
use piton_core::value::{AnchorId, Dict, Value};

use crate::markdown::{block, front_matter, humanize, kebab, remainder};
use crate::module;
// ---- instructions --------------------------------------------------------

/// Mirror the shape tree onto the code tree.
fn instruction_files(
    compilation: &Compilation,
    settings: &Settings,
    adapter: &Adapter,
    plan: &Plan,
) -> Vec<OutputFile> {
    let mut by_target: BTreeMap<PathBuf, Vec<String>> = BTreeMap::new();
    let mut files = Vec::new();

    for id in &plan.instructions {
        let Some(anchor) = compilation.anchor(*id) else { continue };
        let body = instruction_body(&anchor.name, &anchor.props);
        let source = compilation.source_path(*id).map(Path::to_path_buf);

        let relative = source
            .as_ref()
            .zip(settings.shape_root.as_ref())
            .and_then(|(source, root)| source.strip_prefix(root).ok())
            .map(Path::to_path_buf);
        let scope = relative
            .as_ref()
            .and_then(|path| path.parent())
            .map(Path::to_path_buf)
            .unwrap_or_default();
        by_target.entry(nearest_existing(&settings.code_root, &scope)).or_default().push(body.clone());

        // Every instruction is also published under the agent directory.
        if let Some(source) = source {
            files.push(OutputFile {
                path: settings
                    .base
                    .join(reference_path(settings, adapter, &source, &anchor.name)),
                contents: body,
            });
        }
    }

    // A self-instruction is about the specification, so it stays beside it.
    // It is not published under the agent directory: it is not shape, and a
    // reference to one publishes it the way any other anchor is.
    for id in &plan.self_instructions {
        let Some(anchor) = compilation.anchor(*id) else { continue };
        let Some(directory) = compilation.source_path(*id).and_then(Path::parent) else {
            continue;
        };
        by_target
            .entry(directory.to_path_buf())
            .or_default()
            .push(instruction_body(&anchor.name, &anchor.props));
    }

    for (directory, bodies) in by_target {
        files.push(OutputFile {
            path: directory.join("AGENTS.md"),
            contents: format!("{}\n", bodies.join("\n\n").trim_end()),
        });
        // Claude Code reads `CLAUDE.md`, not `AGENTS.md`, and its documentation
        // recommends a `CLAUDE.md` that imports the `AGENTS.md` beside it. The
        // import resolves against the importing file and only this one file is
        // inlined: the references inside it are links, which nothing expands.
        if adapter.is_claude() {
            files.push(OutputFile {
                path: directory.join("CLAUDE.md"),
                contents: "@AGENTS.md\n".to_string(),
            });
        }
    }
    files
}

/// Walk up from a mirrored path until a real code directory is found.
fn nearest_existing(code_root: &Path, scope: &Path) -> PathBuf {
    let mut candidate = scope.to_path_buf();
    loop {
        let target = code_root.join(&candidate);
        if target.is_dir() {
            return target;
        }
        match candidate.parent() {
            Some(parent) if !candidate.as_os_str().is_empty() => candidate = parent.to_path_buf(),
            _ => return code_root.to_path_buf(),
        }
    }
}

// ---- references -----------------------------------------------------------
export abstract anchor SelfInstruction as self-instruction:
    description:: string: ""
    prompt:: string

// Belay's project configuration.
export abstract anchor BelayConfig as belay-config:
    codeRoot:: string

// The base of every output adapter.
export abstract anchor Adapter as belay-adapter:
    description:: string

// Writes agentic Markdown for tools such as Claude Code.
export abstract anchor AgentAdapter extends Adapter as belay-agent-adapter:
    description:: string

// A ready-made adapter that writes into `.claude`.
export anchor ClaudeAdapter extends AgentAdapter:
    description: Writes agentic Markdown into the .claude directory
    claude: true

// A ready-made adapter that writes into `.opencode`.
export anchor OpenCodeAdapter extends AgentAdapter:
    description: Writes agentic Markdown into the .opencode directory
    opencode: true

// The compiled shape directory, so skills can point agents at it.
export __BELAY_SHAPE__: {shape_path}
"#
    )
}
